import {
  FrontSide,
  MeshBasicMaterial,
  WireframeGeometry,
  type BufferGeometry,
  type Material,
  type Mesh,
  type Object3D,
} from 'three';
import { LineMaterial } from 'three/examples/jsm/lines/LineMaterial.js';
import { LineSegments2 } from 'three/examples/jsm/lines/LineSegments2.js';
import { LineSegmentsGeometry } from 'three/examples/jsm/lines/LineSegmentsGeometry.js';
import type { Model3DWireframe } from '../../specification/nodes/model3d';

export interface InstalledWireframe {
  materials: Material[];
  geometries: BufferGeometry[];
}

/**
 * Installs a wide-line wireframe on a cloned GLTF scene. LineSegments2 gives
 * deterministic pixel thickness across WebGL implementations. A colorless,
 * slightly offset depth pre-pass hides rear edges when culling is requested
 * without z-fighting against the visible lines.
 */
export function installWireframe(
  root: Object3D,
  settings: Model3DWireframe,
  backfaceCulling: boolean,
): InstalledWireframe {
  const materials: Material[] = [];
  const geometries: BufferGeometry[] = [];
  const geometryCache = new Map<BufferGeometry, LineSegmentsGeometry>();
  const meshes: Mesh[] = [];

  root.traverse((object) => {
    const mesh = object as Mesh;
    if (mesh.isMesh && mesh.geometry?.attributes.position) meshes.push(mesh);
  });

  for (const mesh of meshes) {
    let lineGeometry = geometryCache.get(mesh.geometry);
    if (!lineGeometry) {
      const nativeWireframe = new WireframeGeometry(mesh.geometry);
      lineGeometry = new LineSegmentsGeometry().fromWireframeGeometry(nativeWireframe);
      nativeWireframe.dispose();
      geometryCache.set(mesh.geometry, lineGeometry);
      geometries.push(lineGeometry);
    }

    const depthMaterial = new MeshBasicMaterial({
      colorWrite: false,
      depthWrite: backfaceCulling,
      depthTest: backfaceCulling,
      side: FrontSide,
      polygonOffset: backfaceCulling,
      polygonOffsetFactor: 1,
      polygonOffsetUnits: 1,
    });
    mesh.material = depthMaterial;
    mesh.castShadow = false;
    mesh.receiveShadow = false;
    materials.push(depthMaterial);

    const lineMaterial = new LineMaterial({
      color: settings.color,
      linewidth: settings.thickness,
      worldUnits: false,
      depthTest: backfaceCulling,
      depthWrite: false,
      transparent: false,
      alphaToCoverage: true,
    });
    materials.push(lineMaterial);

    const lines = new LineSegments2(lineGeometry, lineMaterial);
    lines.name = 'AMP Wireframe';
    lines.frustumCulled = false;
    lines.renderOrder = mesh.renderOrder + 1;
    mesh.add(lines);
  }

  return { materials, geometries };
}
