export interface ModelDimensions {
  x: number;
  y: number;
  z: number;
}

export interface ViewportDimensions {
  width: number;
  height: number;
}

export interface PerspectiveFit {
  distance: number;
  near: number;
  far: number;
}

// Fits the model's actual axis-aligned 3D dimensions into the view without
// changing its proportions. Depth is included so the model's front-most
// point, rather than only its center plane, remains inside the frustum.
export function computePerspectiveFit(
  model: ModelDimensions,
  viewport: ViewportDimensions,
  verticalFovDegrees = 45,
  padding = 1.15,
): PerspectiveFit {
  const width = finitePositive(model.x);
  const height = finitePositive(model.y);
  const depth = finitePositive(model.z);
  const aspect = finitePositive(viewport.width) / finitePositive(viewport.height);
  const verticalFov = (verticalFovDegrees * Math.PI) / 180;
  const horizontalFov = 2 * Math.atan(Math.tan(verticalFov / 2) * aspect);

  const distanceForWidth = width / (2 * Math.tan(horizontalFov / 2));
  const distanceForHeight = height / (2 * Math.tan(verticalFov / 2));
  const distanceToFront = Math.max(distanceForWidth, distanceForHeight) * Math.max(1, padding);
  const distance = distanceToFront + depth / 2;

  return {
    distance,
    near: Math.max(0.001, distanceToFront * 0.01),
    far: Math.max(distance + depth * 2, distance * 10),
  };
}

function finitePositive(value: number): number {
  return Number.isFinite(value) && value > 0 ? value : 0.001;
}
