import { BackSide, Color, MeshBasicMaterial, type Material, type Mesh, type Object3D } from 'three';
import { clone } from 'three/examples/jsm/utils/SkeletonUtils.js';

export interface ModelOutlineSettings {
  enabled: boolean;
  color: string;
  thickness: number;
  opacity: number;
}

/**
 * Creates an inverted-hull outline while continuing to share all geometry.
 * This costs one extra draw per mesh only when explicitly enabled.
 */
export function createModelOutline(source: Object3D, settings: ModelOutlineSettings) {
  if (!settings.enabled || settings.thickness <= 0 || settings.opacity <= 0) return null;
  const instance = clone(source);
  const materialCache = new Map<Material, MeshBasicMaterial>();
  const ownedMaterials: MeshBasicMaterial[] = [];

  instance.traverse((object) => {
    const mesh = object as Mesh;
    if (!mesh.isMesh || !mesh.material) return;
    const convert = (sourceMaterial: Material) => {
      const cached = materialCache.get(sourceMaterial);
      if (cached) return cached;
      const material = new MeshBasicMaterial({
        color: new Color(settings.color),
        side: BackSide,
        transparent: settings.opacity < 1,
        opacity: settings.opacity,
        depthWrite: false,
        depthTest: true,
        toneMapped: false,
      });
      materialCache.set(sourceMaterial, material);
      ownedMaterials.push(material);
      return material;
    };
    mesh.material = Array.isArray(mesh.material) ? mesh.material.map(convert) : convert(mesh.material);
    mesh.renderOrder = -1;
  });
  const scale = 1 + settings.thickness;
  instance.scale.setScalar(scale);
  // The fitted source is translated so its bounds center is at the origin.
  // Scale that centering translation too, keeping an off-origin asset's
  // outline perfectly concentric instead of drifting as width increases.
  instance.position.multiplyScalar(scale);
  return { instance, ownedMaterials };
}
