import {
  Color,
  DoubleSide,
  FrontSide,
  MeshStandardMaterial,
  Vector2,
  type Material,
  type Mesh,
  type Object3D,
  type Texture,
} from 'three';
import type { Model3DToon } from '../../specification/nodes/model3d';
import type { Model3DMaterialOverride } from '../../specification/nodes/model3d';

interface CompatibleMaterial extends Material {
  color?: Color;
  map?: Texture | null;
  normalMap?: Texture | null;
  normalScale?: Vector2;
  roughness?: number;
  roughnessMap?: Texture | null;
  metalness?: number;
  metalnessMap?: Texture | null;
  alphaMap?: Texture | null;
  aoMap?: Texture | null;
  emissive?: Color;
  emissiveMap?: Texture | null;
  emissiveIntensity?: number;
}

const generatedNormals = new WeakSet<object>();

/**
 * Installs a small PBR-aware toon stage on private material clones. Geometry,
 * textures and the cached GLTF remain shared, so enabling toon does not
 * duplicate the expensive parts of a high-triangle model.
 */
export function installToonMaterials(
  root: Object3D,
  settings: Model3DToon,
  override?: Model3DMaterialOverride,
  backfaceCulling = true,
): Material[] {
  const materialCache = new Map<Material, Material>();
  const ownedMaterials: Material[] = [];

  root.traverse((object) => {
    const mesh = object as Mesh;
    if (!mesh.isMesh || !mesh.material) return;

    if (!mesh.geometry.attributes.normal && !generatedNormals.has(mesh.geometry)) {
      mesh.geometry.computeVertexNormals();
      generatedNormals.add(mesh.geometry);
    }

    const convert = (source: Material) => {
      const cached = materialCache.get(source);
      if (cached) return cached;
      const toon = createModelMaterial(source as CompatibleMaterial, settings, override, backfaceCulling);
      materialCache.set(source, toon);
      ownedMaterials.push(toon);
      return toon;
    };

    mesh.material = Array.isArray(mesh.material)
      ? mesh.material.map(convert)
      : convert(mesh.material);
  });

  return ownedMaterials;
}

function createModelMaterial(
  source: CompatibleMaterial,
  settings: Model3DToon,
  override?: Model3DMaterialOverride,
  backfaceCulling = true,
): MeshStandardMaterial {
  const isStandard = 'isMeshStandardMaterial' in source && source.isMeshStandardMaterial === true;
  const material = isStandard
    ? (source as MeshStandardMaterial).clone()
    : new MeshStandardMaterial({
        color: source.color?.clone() ?? new Color(0xffffff),
        map: source.map ?? null,
        normalMap: source.normalMap ?? null,
        normalScale: source.normalScale?.clone() ?? new Vector2(1, 1),
        roughness: source.roughness ?? 0.8,
        roughnessMap: source.roughnessMap ?? null,
        metalness: source.metalness ?? 0,
        metalnessMap: source.metalnessMap ?? null,
        alphaMap: source.alphaMap ?? null,
        aoMap: source.aoMap ?? null,
        emissive: source.emissive?.clone() ?? new Color(0x000000),
        emissiveMap: source.emissiveMap ?? null,
        emissiveIntensity: source.emissiveIntensity ?? 1,
        opacity: source.opacity,
        transparent: source.transparent,
        side: source.side,
        depthTest: source.depthTest,
        depthWrite: source.depthWrite,
        alphaTest: source.alphaTest,
      });

  const sourceRoughness = override?.enabled ? override.roughness : (source.roughness ?? material.roughness);
  const sourceMetalness = override?.enabled ? override.metalness : (source.metalness ?? material.metalness);
  if (override?.enabled) material.color.set(override.baseColor);
  material.roughness = clamp(sourceRoughness * settings.roughnessMultiplier, 0, 1);
  material.metalness = clamp(sourceMetalness * settings.metalnessMultiplier, 0, 1);
  material.opacity = clamp(source.opacity * settings.opacityMultiplier, 0, 1);
  material.transparent = source.transparent || material.opacity < 1 || Boolean(material.alphaMap);
  material.normalScale.multiplyScalar(settings.normalScale);
  material.side = backfaceCulling ? FrontSide : DoubleSide;
  const ao = settings.ao ?? { enabled: true, intensity: 1 };
  material.aoMapIntensity = ao.enabled ? ao.intensity : 0;

  if (!settings.enabled) {
    material.needsUpdate = true;
    return material;
  }

  const previousCompile = material.onBeforeCompile.bind(material);
  const previousCacheKey = material.customProgramCacheKey.bind(material);
  material.onBeforeCompile = (shader, renderer) => {
    previousCompile(shader, renderer);
    const marker = 'vec3 outgoingLight = totalDiffuse + totalSpecular + totalEmissiveRadiance;';
    shader.uniforms.ampToonBands = { value: settings.bands };
    shader.uniforms.ampToonStrength = { value: settings.strength };
    shader.uniforms.ampToonSoftness = { value: settings.smoothness };
    shader.uniforms.ampAoIntensity = { value: ao.intensity };
    shader.fragmentShader = shader.fragmentShader.replace(
      '#include <common>',
      [
        '#include <common>',
        'uniform float ampToonBands;',
        'uniform float ampToonStrength;',
        'uniform float ampToonSoftness;',
        'uniform float ampAoIntensity;',
      ].join('\n'),
    );
    const approximateAo = ao.enabled && !material.aoMap
      ? [
          'float ampNormalVariation = clamp(length(fwidth(normal)) * 0.4, 0.0, 1.0);',
          'float ampHemisphere = 0.72 + 0.28 * smoothstep(-0.4, 0.8, normal.y);',
          'float ampAmbientOcclusion = clamp((1.0 - ampNormalVariation * 0.45 * ampAoIntensity) * mix(1.0, ampHemisphere, min(ampAoIntensity, 1.0)), 0.35, 1.0);',
          'outgoingLight *= ampAmbientOcclusion;',
        ]
      : [];
    const toonStage = [
      marker,
      ...approximateAo,
      // Quantize in perceptual, tone-mapped luminance. This spreads ordinary
      // PBR illumination across the complete authored band range instead of
      // compressing most models into one or two nearly identical bright bands.
      'float ampToonLuma = max(dot(outgoingLight, vec3(0.2126, 0.7152, 0.0722)), 0.00001);',
      'float ampToonDisplay = pow(clamp(ampToonLuma / (1.0 + ampToonLuma), 0.0, 0.9999), 0.454545);',
      'float ampToonIntervals = max(ampToonBands - 1.0, 1.0);',
      'float ampToonScaled = ampToonDisplay * ampToonIntervals;',
      'float ampToonLow = floor(ampToonScaled);',
      'float ampToonEdge = fract(ampToonScaled);',
      // Derivative-based minimum smoothing removes shimmer on high-triangle
      // meshes while the authored softness remains plainly visible.
      'float ampToonTransition = min(0.499, max(ampToonSoftness, fwidth(ampToonScaled) * 0.75));',
      'float ampToonBlend = smoothstep(0.5 - ampToonTransition, 0.5 + ampToonTransition, ampToonEdge);',
      'float ampToonQuantized = clamp((ampToonLow + ampToonBlend) / ampToonIntervals, 0.0001, 0.9999);',
      'float ampToonLinear = pow(ampToonQuantized, 2.2);',
      'float ampToonTarget = ampToonLinear / max(1.0 - ampToonLinear, 0.0001);',
      'float ampToonGain = clamp(ampToonTarget / ampToonLuma, 0.18, 4.0);',
      'vec3 ampToonColor = outgoingLight * ampToonGain;',
      'outgoingLight = mix(outgoingLight, ampToonColor, ampToonStrength);',
    ].join('\n');
    shader.fragmentShader = shader.fragmentShader.replace(marker, toonStage);
  };
  material.customProgramCacheKey = () => [
    previousCacheKey(),
    'amp-toon-v2',
    ao.enabled && !material.aoMap ? 'approx-ao' : 'native-ao',
  ].join(':');
  material.needsUpdate = true;
  return material;
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}
