import { Component, Suspense, useCallback, useEffect, useMemo, useRef, useState, type ReactNode, type RefObject } from 'react';
import { useFrame, useThree } from '@react-three/fiber';
import { ContactShadows, Environment, PerspectiveCamera, useGLTF, View } from '@react-three/drei';
import { Box3, Vector3, type Group } from 'three';
import { clone } from 'three/examples/jsm/utils/SkeletonUtils.js';
import type { Model3DNode } from '../../specification/nodes';
import { computePerspectiveFit } from '../../author/model/model3d-fit';
import { installToonMaterials } from '../../author/canvas/model3d-toon-material';
import { createModelOutline } from '../../author/canvas/model3d-outline';
import { installWireframe } from '../../author/canvas/model3d-wireframe';
import { retainModelResource } from '../../author/canvas/model3d-resource-cache';

const DEFAULT_TOON = {
  enabled: true, bands: 4, strength: 0.7, smoothness: 0.08,
  roughnessMultiplier: 1, metalnessMultiplier: 1, opacityMultiplier: 1, normalScale: 1,
  ao: { enabled: true, intensity: 1 },
  outline: { enabled: false, color: '#15171a', thickness: 0.018, opacity: 1 },
} as const;
const DEFAULT_SPEED = { x: 0, y: 28.65, z: 0 } as const;
const DEFAULT_WIREFRAME = { enabled: false, color: '#22d3ee', thickness: 1.5 } as const;
const DEG = Math.PI / 180;
const indexes = new Map<string, number>();
const contexts = new WeakMap<HTMLCanvasElement, CanvasRenderingContext2D>();
let nextIndex = 1;

function viewIndex(id: string) {
  const known = indexes.get(id);
  if (known !== undefined) return known;
  const created = nextIndex++;
  indexes.set(id, created);
  return created;
}

export default function RuntimeModel3DView({ node, src, visible, hovered, presentationRef, onReady, onError }: {
  node: Model3DNode;
  src: string;
  visible: boolean;
  hovered: boolean;
  presentationRef: RefObject<HTMLCanvasElement | null>;
  onReady: () => void;
  onError: (message: string) => void;
}) {
  const track = useRef<HTMLDivElement>(null);
  const [ready, setReady] = useState(false);
  const index = viewIndex(node.id);
  const light = lightingFor(node.lighting ?? 'studio');
  const intensity = node.lightingIntensity ?? 1;
  const wireframe = node.wireframe?.enabled ?? false;
  const contentReady = useCallback(() => { setReady(true); onReady(); }, [onReady]);
  return (
    <View ref={track} index={index} visible={visible} frames={Infinity} className="amp-runtime-model-view">
      <DepthReset track={track} index={index} />
      {!wireframe && <ambientLight intensity={light.ambient * intensity} />}
      {!wireframe && <directionalLight position={light.position} intensity={light.directional * intensity} />}
      {!wireframe && node.environment && node.environment !== 'none' && <Environment preset={node.environment} background={false} environmentIntensity={intensity} />}
      <SceneBoundary resetKey={src} onError={onError}>
        <Suspense fallback={null}>
          <GLTFModel node={node} src={src} visible={visible} hovered={hovered} onReady={contentReady} />
        </Suspense>
      </SceneBoundary>
      <Snapshot track={track} target={presentationRef} index={index} visible={visible} ready={ready} dynamic={node.behaviors.autoRotate} revision={node} />
    </View>
  );
}

function GLTFModel({ node, src, visible, hovered, onReady }: { node: Model3DNode; src: string; visible: boolean; hovered: boolean; onReady: () => void }) {
  const { scene } = useGLTF(src);
  const size = useThree((state) => state.size);
  const toon = node.toon ?? DEFAULT_TOON;
  const wireframe = node.wireframe ?? DEFAULT_WIREFRAME;
  const prepared = useMemo(() => {
    const instance = clone(scene);
    const box = new Box3().setFromObject(instance);
    const dimensions = box.isEmpty() ? new Vector3(1, 1, 1) : box.getSize(new Vector3());
    const center = box.isEmpty() ? new Vector3() : box.getCenter(new Vector3());
    instance.position.sub(center);
    if (wireframe.enabled) {
      const installed = installWireframe(instance, wireframe, node.backfaceCulling ?? true);
      return { instance, dimensions, materials: installed.materials, geometries: installed.geometries, outline: null };
    }
    const materials = installToonMaterials(instance, toon, node.materialOverride, node.backfaceCulling ?? true);
    const outline = createModelOutline(instance, toon.outline ?? DEFAULT_TOON.outline);
    return { instance, dimensions, materials, geometries: [], outline };
  }, [node.backfaceCulling, node.materialOverride, scene, toon, wireframe]);
  const fov = Math.min(120, Math.max(10, node.camera?.fov ?? 45));
  const fit = useMemo(() => computePerspectiveFit(prepared.dimensions, size, fov), [fov, prepared.dimensions, size]);
  const rotating = visible && node.behaviors.autoRotate && !(hovered && node.behaviors.pauseOnHover);
  const speed = node.behaviors.rotationSpeed ?? DEFAULT_SPEED;
  const offset = node.behaviors.rotationOffset?.enabled ? node.behaviors.rotationOffset : null;
  const group = useRef<Group>(null);

  useEffect(() => { onReady(); }, [onReady, scene]);
  useEffect(() => retainModelResource(src, scene), [scene, src]);
  useEffect(() => () => {
    prepared.materials.forEach((material) => material.dispose());
    prepared.geometries.forEach((geometry) => geometry.dispose());
    prepared.outline?.ownedMaterials.forEach((material) => material.dispose());
  }, [prepared]);
  useFrame((_state, delta) => {
    if (!group.current || !rotating) return;
    group.current.rotation.x += delta * speed.x * DEG;
    group.current.rotation.y += delta * speed.y * DEG;
    group.current.rotation.z += delta * speed.z * DEG;
  });

  return <>
    <PerspectiveCamera makeDefault fov={fov} near={fit.near} far={fit.far} position={[0, 0, fit.distance]} />
    <group rotation={offset ? [offset.x * DEG, offset.y * DEG, offset.z * DEG] : [0, 0, 0]}>
      <group ref={group}>
        {prepared.outline && <primitive object={prepared.outline.instance} dispose={null} />}
        <primitive object={prepared.instance} dispose={null} />
      </group>
    </group>
    {!wireframe.enabled && node.shadows && node.shadows !== 'none' && <ContactShadows
      frames={1}
      resolution={128}
      position={[0, -prepared.dimensions.y / 2, 0]}
      far={Math.max(0.1, prepared.dimensions.y * 2)}
      opacity={0.5}
      blur={node.shadows === 'soft' ? 2.25 : 0.35}
      scale={Math.max(prepared.dimensions.x, prepared.dimensions.z, 0.1) * 1.5}
    />}
  </>;
}

function DepthReset({ track, index }: { track: RefObject<HTMLElement | null>; index: number }) {
  const gl = useThree((state) => state.gl);
  useFrame(() => {
    const element = track.current;
    if (!element) return;
    const rect = element.getBoundingClientRect();
    const source = gl.domElement.getBoundingClientRect();
    const left = Math.max(0, rect.left - source.left);
    const bottom = Math.max(0, source.bottom - rect.bottom);
    const width = Math.max(0, Math.min(rect.right, source.right) - Math.max(rect.left, source.left));
    const height = Math.max(0, Math.min(rect.bottom, source.bottom) - Math.max(rect.top, source.top));
    if (!width || !height) return;
    gl.setScissor(left, bottom, width, height);
    gl.setScissorTest(true);
    gl.clear(true, true, false);
    gl.setScissorTest(false);
  }, index - 0.25);
  return null;
}

function Snapshot({ track, target, index, visible, ready, dynamic, revision }: {
  track: RefObject<HTMLElement | null>;
  target: RefObject<HTMLCanvasElement | null>;
  index: number;
  visible: boolean;
  ready: boolean;
  dynamic: boolean;
  revision: unknown;
}) {
  const gl = useThree((state) => state.gl);
  const previous = useRef<{ revision: unknown; width: number; height: number } | null>(null);
  useFrame(() => {
    if (!visible || !ready) return;
    const element = track.current;
    const canvas = target.current;
    if (!element || !canvas) return;
    const rect = element.getBoundingClientRect();
    const source = gl.domElement.getBoundingClientRect();
    const width = Math.max(1, Math.round(rect.width));
    const height = Math.max(1, Math.round(rect.height));
    const last = previous.current;
    if (!dynamic && last?.revision === revision && last?.width === width && last?.height === height) return;
    if (canvas.width !== width) canvas.setAttribute('width', String(width));
    if (canvas.height !== height) canvas.setAttribute('height', String(height));
    let context = contexts.get(canvas);
    if (!context) {
      const next = canvas.getContext('2d', { willReadFrequently: true });
      if (!next) return;
      context = next;
      contexts.set(canvas, context);
    }
    context.clearRect(0, 0, width, height);
    const left = Math.max(rect.left, source.left);
    const top = Math.max(rect.top, source.top);
    const right = Math.min(rect.right, source.right);
    const bottom = Math.min(rect.bottom, source.bottom);
    if (right <= left || bottom <= top) return;
    const sourceScaleX = gl.domElement.width / Math.max(1, source.width);
    const sourceScaleY = gl.domElement.height / Math.max(1, source.height);
    const destinationScaleX = width / Math.max(1, rect.width);
    const destinationScaleY = height / Math.max(1, rect.height);
    context.drawImage(gl.domElement,
      (left - source.left) * sourceScaleX, (top - source.top) * sourceScaleY,
      (right - left) * sourceScaleX, (bottom - top) * sourceScaleY,
      (left - rect.left) * destinationScaleX, (top - rect.top) * destinationScaleY,
      (right - left) * destinationScaleX, (bottom - top) * destinationScaleY,
    );
    previous.current = { revision, width, height };
    canvas.dispatchEvent(new CustomEvent('amp-model-frame', { bubbles: true }));
  }, index + 0.25);
  return null;
}

class SceneBoundary extends Component<{ resetKey: string; onError: (message: string) => void; children: ReactNode }, { failed: boolean }> {
  state = { failed: false };
  static getDerivedStateFromError() { return { failed: true }; }
  componentDidCatch(error: unknown) { this.props.onError(error instanceof Error ? error.message : String(error)); }
  componentDidUpdate(previous: Readonly<{ resetKey: string }>) {
    if (previous.resetKey !== this.props.resetKey && this.state.failed) this.setState({ failed: false });
  }
  render() { return this.state.failed ? null : this.props.children; }
}

function lightingFor(preset: NonNullable<Model3DNode['lighting']>) {
  switch (preset) {
    case 'soft': return { ambient: 1, directional: 0.65, position: [4, 6, 4] as const };
    case 'dramatic': return { ambient: 0.2, directional: 2, position: [-4, 6, 2] as const };
    case 'neutral': return { ambient: 0.75, directional: 0.8, position: [2, 4, 3] as const };
    case 'outdoor': return { ambient: 0.9, directional: 1.4, position: [6, 8, 3] as const };
    case 'studio': return { ambient: 0.55, directional: 1.25, position: [3, 5, 2] as const };
  }
}
