import { useGLTF } from '@react-three/drei';
import type { BufferGeometry, Material, Mesh, Object3D, Texture } from 'three';

interface ResourceEntry {
  references: number;
  scene: Object3D;
  disposeTimer: ReturnType<typeof setTimeout> | null;
}

const resources = new Map<string, ResourceEntry>();

export function retainModelResource(src: string, scene: Object3D): () => void {
  let entry = resources.get(src);
  if (!entry) {
    entry = { references: 0, scene, disposeTimer: null };
    resources.set(src, entry);
  }
  entry.references += 1;
  if (entry.disposeTimer) {
    clearTimeout(entry.disposeTimer);
    entry.disposeTimer = null;
  }

  let released = false;
  return () => {
    if (released) return;
    released = true;
    const current = resources.get(src);
    if (!current) return;
    current.references = Math.max(0, current.references - 1);
    if (current.references > 0) return;
    // Defer disposal through the current task so React StrictMode and quick
    // node moves/remounts can retain the same cache entry without reloading.
    current.disposeTimer = setTimeout(() => {
      const latest = resources.get(src);
      if (!latest || latest.references > 0) return;
      useGLTF.clear(src);
      disposeSceneResources(latest.scene);
      resources.delete(src);
    }, 0);
  };
}

export function disposeSceneResources(scene: Object3D): void {
  const geometries = new Set<BufferGeometry>();
  const materials = new Set<Material>();
  const textures = new Set<Texture>();
  scene.traverse((object) => {
    const mesh = object as Mesh;
    if (!mesh.isMesh) return;
    if (mesh.geometry) geometries.add(mesh.geometry);
    const meshMaterials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
    for (const material of meshMaterials) {
      if (!material) continue;
      materials.add(material);
      for (const value of Object.values(material)) {
        if (value && typeof value === 'object' && 'isTexture' in value && value.isTexture === true) {
          textures.add(value as Texture);
        }
      }
    }
  });
  geometries.forEach((geometry) => geometry.dispose());
  materials.forEach((material) => material.dispose());
  textures.forEach((texture) => texture.dispose());
}
